cat >> ch03c.html <<'EOF'
<script>
(function(){
"use strict";
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const NS="http://www.w3.org/2000/svg";
function el(t,a,x){const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);if(x!=null)e.textContent=x;return e;}
function cv(n){return getComputedStyle(document.body).getPropertyValue(n).trim();}

$("#tbtn").onclick=()=>{const c=document.documentElement.getAttribute("data-theme");
  document.documentElement.setAttribute("data-theme",c==="dark"?"light":"dark");draw1();draw2();draw3();};
const secs=$$("main section"),links=$$("#toc a:not(.sub)");
function onScroll(){const h=document.documentElement;
  $("#prog").style.width=(h.scrollTop/(h.scrollHeight-h.clientHeight)*100)+"%";
  let cur=secs[0].id;for(const s of secs)if(s.getBoundingClientRect().top<=120)cur=s.id;
  links.forEach(a=>a.classList.toggle("on",a.getAttribute("href")==="#"+cur));}
document.addEventListener("scroll",onScroll,{passive:true});onScroll();

/* ══════════════════════════════════════════════════════════════════
   实验 1 · 崩溃重启：漏掉一样持久化状态会怎样
   ══════════════════════════════════════════════════════════════════ */
const N1=["N1","N2","N3","N4","N5"];
function nd(role,term,vote,dead){return {role,term,vote,dead:!!dead};}
const SC1=[
 {n:"全部持久化（正确）",disk:"currentTerm ✓　votedFor ✓　log ✓",steps:[
  {t:"任期 5：N1 和 N2 同时成为 Candidate",
   s:[nd("C",5,"N1"),nd("C",5,"N2"),nd("F",5,"—"),nd("F",5,"—"),nd("F",5,"—")],
   note:"两个节点同时超时，各自 term++ 到 5，都先投了自己一票。过半需要 <strong>3 票</strong>。"},
  {t:"N3 投给 N1，N4 投给 N2 —— 两边都是 2 票",
   s:[nd("C",5,"N1"),nd("C",5,"N2"),nd("F",5,"N1"),nd("F",5,"N2"),nd("F",5,"—")],
   note:"N1 有 {N1,N3} = 2 票，N2 有 {N2,N4} = 2 票。<strong>N5 的那一票决定一切。</strong>"},
  {t:"N5 投给 N1 → N1 拿到 3 票当选",
   s:[nd("L",5,"N1"),nd("C",5,"N2"),nd("F",5,"N1"),nd("F",5,"N2"),nd("F",5,"N1")],
   hi:[4],note:"N1 集齐 {N1,N3,N5} = 3 票，成为任期 5 的 Leader。<br>N5 <strong>把 votedFor=N1 写进了磁盘</strong>，然后才回复投票。"},
  {t:"N5 崩溃重启",
   s:[nd("L",5,"N1"),nd("C",5,"N2"),nd("F",5,"N1"),nd("F",5,"N2"),nd("F",5,"N1",true)],
   hi:[4],note:"N5 掉电了。它的内存全没了，但磁盘上的三样状态还在。"},
  {t:"N5 从磁盘读回 votedFor=N1，拒绝 N2",
   s:[nd("L",5,"N1"),nd("C",5,"N2"),nd("F",5,"N1"),nd("F",5,"N2"),nd("F",5,"N1")],
   hi:[4],ok:true,
   note:"N5 恢复后<strong>记得自己在任期 5 已经投过票了</strong>，所以拒绝 N2 的索票。<br>N2 停在 2 票，永远选不上。<strong>任期 5 只有 N1 一个 Leader。</strong>"}]},
 {n:"丢失 votedFor",disk:"currentTerm ✓　<span style='color:var(--crit)'>votedFor ✗</span>　log ✓",steps:[
  {t:"任期 5：N1 和 N2 同时成为 Candidate",
   s:[nd("C",5,"N1"),nd("C",5,"N2"),nd("F",5,"—"),nd("F",5,"—"),nd("F",5,"—")],
   note:"和上一个场景完全相同的开局。"},
  {t:"N3 投给 N1，N4 投给 N2 —— 两边都是 2 票",
   s:[nd("C",5,"N1"),nd("C",5,"N2"),nd("F",5,"N1"),nd("F",5,"N2"),nd("F",5,"—")],
   note:"N1 有 2 票，N2 有 2 票。过半需要 3 票。"},
  {t:"N5 投给 N1 → N1 当选",
   s:[nd("L",5,"N1"),nd("C",5,"N2"),nd("F",5,"N1"),nd("F",5,"N2"),nd("F",5,"N1")],
   hi:[4],note:"N1 集齐 {N1,N3,N5} = 3 票当选。<br><strong style='color:var(--crit)'>但 N5 只把 votedFor 记在了内存里。</strong>"},
  {t:"N5 崩溃重启 —— votedFor 没了",
   s:[nd("L",5,"N1"),nd("C",5,"N2"),nd("F",5,"N1"),nd("F",5,"N2"),nd("F",5,"—",true)],
   hi:[4],note:"N5 掉电重启。<code>currentTerm=5</code> 从磁盘读回来了，但 <code>votedFor</code> 变成了空——<strong>它忘了自己投过票。</strong>"},
  {t:"N5 又投给了 N2 → 同一任期第二个 Leader",
   s:[nd("L",5,"N1"),nd("L",5,"N2"),nd("F",5,"N1"),nd("F",5,"N2"),nd("F",5,"N2")],
   hi:[0,1,4],bad:true,
   note:"N2 还在索票。N5 觉得自己本任期还没投过，于是投给了 N2。<br>N2 集齐 {N2,N4,N5} = 3 票，<strong style='color:var(--crit)'>在同一个任期 5 里也当选了 Leader</strong>。<br>两个 Leader 的票集合分别是 {N1,N3,N5} 和 {N2,N4,N5}——<em>它们的交集 {N5} 在同一任期投了两票</em>。"}]},
 {n:"丢失 currentTerm",disk:"<span style='color:var(--crit)'>currentTerm ✗</span>　votedFor ✓　log ✓",steps:[
  {t:"任期 8：N1 是 Leader，集群正常",
   s:[nd("L",8,"N1"),nd("F",8,"N1"),nd("F",8,"N1"),nd("F",8,"N1"),nd("F",8,"N1")],
   note:"集群已经跑到任期 8。所有节点的 currentTerm 都是 8。"},
  {t:"N5 崩溃重启 —— currentTerm 归零",
   s:[nd("L",8,"N1"),nd("F",8,"N1"),nd("F",8,"N1"),nd("F",8,"N1"),nd("F",0,"N1",true)],
   hi:[4],note:"N5 重启后 <code>currentTerm</code> 回到 0。它<strong>不再知道自己见过任期 8</strong>。"},
  {t:"N5 接受一个来自任期 3 的过时 Candidate",
   s:[nd("L",8,"N1"),nd("F",8,"N1"),nd("F",8,"N1"),nd("F",8,"N1"),nd("F",3,"旧节点")],
   hi:[4],bad:true,
   note:"一个被隔离很久、还停在任期 3 的节点回来索票。<br>正常情况下 N5 会因为 <code>3 &lt; 8</code> 直接拒绝，但现在它的 term 是 0，<strong>于是接受了这个过时请求并投了票</strong>。<br><em>currentTerm 的作用就是识别并淘汰陈旧信息——丢了它，节点就失去了时间感。</em><br>更糟的是：即使 votedFor 持久化了也救不了，因为 votedFor 是<u>相对于某个任期</u>才有意义的。"}]},
 {n:"丢失 log[]",disk:"currentTerm ✓　votedFor ✓　<span style='color:var(--crit)'>log ✗</span>",steps:[
  {t:"一条日志复制到 {N1,N2,N3}，已提交",
   s:[nd("L",6,"log:[x=1]"),nd("F",6,"log:[x=1]"),nd("F",6,"log:[x=1]"),nd("F",6,"log:[]"),nd("F",6,"log:[]")],
   hi:[0,1,2],note:"3/5 个节点持有 <code>x=1</code>，达到过半，Leader 提交并<strong>回复客户端"成功"</strong>。"},
  {t:"N2、N3 崩溃重启 —— 日志没了",
   s:[nd("L",6,"log:[x=1]"),nd("F",6,"log:[]",true),nd("F",6,"log:[]",true),nd("F",6,"log:[]"),nd("F",6,"log:[]")],
   hi:[1,2],note:"两个节点重启后日志为空。<strong>现在全集群只有 N1 还持有 x=1。</strong>"},
  {t:"N1 崩溃，N4 当选新 Leader",
   s:[nd("F",7,"log:[x=1]",true),nd("F",7,"log:[]"),nd("F",7,"log:[]"),nd("L",7,"log:[]"),nd("F",7,"log:[]")],
   hi:[3],bad:true,
   note:"N1 也挂了。N4 拿到 {N2,N3,N4} 的票当选——<strong>它们的日志都是空的，没人比 N4 更新</strong>，投票规则拦不住它。<br><strong style='color:var(--crit)'>x=1 从此消失，而客户端早已收到"成功"。</strong><br><em>Leader 完整性依赖"持有已提交日志的节点构成过半"这个事实——日志不落盘，这个事实就是假的。</em>"}]}
];
let sc1=0, st1=0, tm1=null;
function draw1(){
  const S=SC1[sc1], P=S.steps[st1], svg=$("#sv1"); svg.innerHTML="";
  const X=[70,200,330,460,590], W=118, Y=52;
  svg.appendChild(el("text",{x:14,y:20,fill:cv("--ink"),"font-size":13,"font-weight":700,"font-family":cv("--sans")},P.t));
  const RC={F:["Follower","--s1"],C:["Candidate","--warn"],L:["Leader","--ok"]};
  P.s.forEach((n,i)=>{
    const hi=(P.hi||[]).includes(i);
    const col=n.dead?cv("--crit"):cv(RC[n.role][1]);
    svg.appendChild(el("rect",{x:X[i],y:Y,width:W,height:62,rx:9,fill:cv("--surface"),
      stroke:hi?cv(P.bad?"--crit":"--warn"):col,"stroke-width":hi?3:2}));
    svg.appendChild(el("text",{x:X[i]+W/2,y:Y+20,fill:cv("--ink"),"font-size":13,"font-weight":700,
      "text-anchor":"middle","font-family":cv("--sans")},(n.dead?"☠ ":"")+N1[i]));
    svg.appendChild(el("text",{x:X[i]+W/2,y:Y+36,fill:col,"font-size":10.5,"font-weight":650,
      "text-anchor":"middle","font-family":cv("--sans")},n.dead?"崩溃重启中":RC[n.role][0]));
    svg.appendChild(el("text",{x:X[i]+W/2,y:Y+52,fill:cv("--ink-3"),"font-size":10,
      "text-anchor":"middle","font-family":cv("--mono")},"t"+n.term+" · "+n.vote));
  });
  // 磁盘条
  svg.appendChild(el("rect",{x:70,y:150,width:638,height:38,rx:8,fill:cv("--surface-2"),stroke:cv("--border")}));
  svg.appendChild(el("text",{x:88,y:174,fill:cv("--ink-3"),"font-size":11.5,"font-family":cv("--sans")},"💾 崩溃后能从磁盘恢复的："));
  const d=el("text",{x:250,y:174,"font-size":12,"font-family":cv("--mono"),fill:cv("--ink")});
  d.innerHTML=S.disk; svg.appendChild(d);
  svg.appendChild(el("text",{x:14,y:212,fill:cv("--ink-3"),"font-size":10.5,"font-family":cv("--sans")},
    "步骤 "+(st1+1)+" / "+S.steps.length));
  const cls=P.bad?"crit":P.ok?"ok":"";
  $("#o1").innerHTML='<div class="note '+cls+'" style="margin:0">'+
    (cls?'<div class="note-h"><span class="dot" style="background:'+(P.ok?cv("--ok"):cv("--crit"))+'"></span>'+
      (P.ok?"安全性成立":"安全性被破坏")+'</div>':'')+'<p style="margin-bottom:0">'+P.note+'</p></div>';
}
function step1(){ if(st1<SC1[sc1].steps.length-1){st1++;draw1();} else {clearInterval(tm1);tm1=null;$("#b1auto").textContent="自动播放";} }
$("#b1step").onclick=step1;
$("#b1auto").onclick=e=>{ if(tm1){clearInterval(tm1);tm1=null;e.target.textContent="自动播放";}
  else{ if(st1>=SC1[sc1].steps.length-1) st1=0; e.target.textContent="暂停"; tm1=setInterval(step1,1600); draw1(); } };
$("#b1reset").onclick=()=>{st1=0;clearInterval(tm1);tm1=null;$("#b1auto").textContent="自动播放";draw1();};
$$("#sc1 button").forEach(b=>b.onclick=()=>{$$("#sc1 button").forEach(x=>x.classList.remove("act"));
  b.classList.add("act");sc1=+b.dataset.s;st1=0;clearInterval(tm1);tm1=null;$("#b1auto").textContent="自动播放";draw1();});
draw1();

/* ══════════════════════════════════════════════════════════════════
   实验 2 · 成员变更裂脑模拟
   ══════════════════════════════════════════════════════════════════ */
const NAMES="ABCDEFGHI".split("");
function draw2(){
  const o=+$("#r2o").value, n=+$("#r2n").value;
  $("#l2o").textContent=o; $("#l2n").textContent=n;
  const U=Math.max(o,n), mo=Math.floor(o/2)+1, mn=Math.floor(n/2)+1;
  const canDisjoint = mo+mn <= U;
  // 构造一对（尽量）不相交的过半集合
  let Sold=[], Snew=[];
  if(o<=n){ for(let i=0;i<mo;i++) Sold.push(i); for(let i=n-mn;i<n;i++) Snew.push(i); }
  else    { for(let i=0;i<mn;i++) Snew.push(i); for(let i=o-mo;i<o;i++) Sold.push(i); }
  const inter=Sold.filter(x=>Snew.includes(x));

  const svg=$("#sv2"); svg.innerHTML="";
  const cw=Math.min(72,640/U), x0=52;
  svg.appendChild(el("text",{x:14,y:20,fill:cv("--ink-3"),"font-size":11,"font-family":cv("--sans")},
    "并集里的全部节点（C_old ∪ C_new，共 "+U+" 个）"));
  for(let i=0;i<U;i++){
    const x=x0+i*cw, inOld=i<o, inNew=i<n;
    const inSo=Sold.includes(i), inSn=Snew.includes(i), both=inter.includes(i);
    svg.appendChild(el("rect",{x:x+3,y:34,width:cw-8,height:46,rx:8,fill:cv("--surface"),
      stroke:both?cv("--s4"):inSo?cv("--s2"):inSn?cv("--s3"):cv("--border"),
      "stroke-width":(inSo||inSn)?2.5:1}));
    svg.appendChild(el("text",{x:x+cw/2-1,y:54,fill:cv("--ink"),"font-size":13,"font-weight":700,
      "text-anchor":"middle","font-family":cv("--sans")},NAMES[i]));
    svg.appendChild(el("text",{x:x+cw/2-1,y:70,fill:cv("--ink-3"),"font-size":9.5,
      "text-anchor":"middle","font-family":cv("--sans")},inOld&&inNew?"旧+新":inOld?"仅旧":"仅新"));
    if(inSo) svg.appendChild(el("text",{x:x+cw/2-1,y:98,fill:cv("--s2"),"font-size":10.5,"font-weight":700,
      "text-anchor":"middle","font-family":cv("--sans")},"旧过半"));
    if(inSn) svg.appendChild(el("text",{x:x+cw/2-1,y:114,fill:cv("--s3"),"font-size":10.5,"font-weight":700,
      "text-anchor":"middle","font-family":cv("--sans")},"新过半"));
    if(both) svg.appendChild(el("text",{x:x+cw/2-1,y:132,fill:cv("--s4"),"font-size":10,"font-weight":700,
      "text-anchor":"middle","font-family":cv("--sans")},"★ 交集"));
  }
  svg.appendChild(el("text",{x:14,y:170,fill:cv("--ink-2"),"font-size":12,"font-family":cv("--mono")},
    "maj_old + maj_new = "+mo+" + "+mn+" = "+(mo+mn)+"　　|C_old ∪ C_new| = "+U));
  svg.appendChild(el("text",{x:14,y:192,fill:canDisjoint?cv("--crit"):cv("--ok"),"font-size":13,"font-weight":700,"font-family":cv("--mono")},
    (mo+mn)+" > "+U+" ？　"+(canDisjoint?"✗ 不成立 ⇒ 可以取到两个不相交的过半集合":"✓ 成立 ⇒ 必然相交，安全")));

  $("#st2").innerHTML=
    '<div class="stat"><div class="k">旧配置过半</div><div class="v" style="color:var(--s2)">'+mo+'</div><div class="u">/ '+o+' 个节点</div></div>'+
    '<div class="stat"><div class="k">新配置过半</div><div class="v" style="color:var(--s3)">'+mn+'</div><div class="u">/ '+n+' 个节点</div></div>'+
    '<div class="stat"><div class="k">两者之和</div><div class="v">'+(mo+mn)+'</div><div class="u">对比并集 '+U+'</div></div>'+
    '<div class="stat"><div class="k">变更幅度</div><div class="v">'+Math.abs(n-o)+'</div><div class="u">个节点</div></div>'+
    '<div class="stat"><div class="k">是否安全</div><div class="v" style="color:'+(canDisjoint?cv("--crit"):cv("--ok"))+'">'+
      (canDisjoint?"✗ 危险":"✓ 安全")+'</div><div class="u">'+(canDisjoint?"可能裂脑":"必然相交")+'</div></div>';

  const fmt=a=>"{"+a.map(i=>NAMES[i]).join(",")+"}";
  $("#o2").innerHTML='<div class="note '+(canDisjoint?"crit":"ok")+'" style="margin:0">'+
    '<div class="note-h"><span class="dot" style="background:'+(canDisjoint?cv("--crit"):cv("--ok"))+'"></span>'+
    (canDisjoint?"能凑出两个不相交的过半集合 ⇒ 同一任期可以出现两个 Leader":"凑不出不相交的过半集合 ⇒ 安全")+'</div>'+
    '<p style="margin-bottom:0">旧配置的一个过半集合：<span class="chip" style="border-color:var(--s2)">'+fmt(Sold)+'</span>　'+
    '新配置的一个过半集合：<span class="chip" style="border-color:var(--s3)">'+fmt(Snew)+'</span><br>'+
    (canDisjoint
      ? '<strong style="color:var(--crit)">这两组没有任何共同节点。</strong>如果前一组还在用旧配置、后一组已经切到新配置，'+
        '它们各自都认为自己凑齐了过半，于是<strong>在同一个任期里选出两个 Leader</strong>——Raft 全部安全性的地基当场塌掉。<br>'+
        '<span style="color:var(--ink-3)">这就是为什么不能一次跨越多个节点。改成一次只动一个（比如 '+o+' → '+(o+(n>o?1:-1))+'）再看。</span>'
      : '<strong style="color:var(--ok)">交集是 '+fmt(inter)+'</strong>——不管你怎么挑，两组必然共享至少一个节点。'+
        '那个节点在同一任期只能投一票，所以两个 Leader 不可能同时出现。<br>'+
        '<span style="color:var(--ink-3)">要凑出不相交的两组需要 '+(mo+mn)+' 个不同节点，而并集里只有 '+U+' 个——鸽笼原理。</span>')+
    '</p></div>';
}
["r2o","r2n"].forEach(i=>$("#"+i).oninput=draw2);
const setON=(o,n)=>{$("#r2o").value=o;$("#r2n").value=n;draw2();};
$("#b2a").onclick=()=>setON(3,5); $("#b2b").onclick=()=>setON(3,4);
$("#b2c").onclick=()=>setON(5,3); $("#b2d").onclick=()=>setON(3,7);
draw2();

/* ══════════════════════════════════════════════════════════════════
   实验 3 · 三种读，同一个僵尸 Leader
   ══════════════════════════════════════════════════════════════════ */
const S3={part:false,written:false,read:false};
function draw3(){
  const svg=$("#sv3"); svg.innerHTML="";
  const zx=[110,240], mx=[420,540,660], Y=80;
  if(S3.part){
    svg.appendChild(el("line",{x1:335,y1:24,x2:335,y2:150,stroke:cv("--crit"),"stroke-width":2.5,"stroke-dasharray":"7 5"}));
    svg.appendChild(el("text",{x:335,y:18,fill:cv("--crit"),"font-size":11,"text-anchor":"middle","font-family":cv("--sans")},"网络分区"));
  }
  const val=S3.written?"x=99":"x=1";
  const node=(x,label,role,v,col,sub)=>{
    svg.appendChild(el("circle",{cx:x,cy:Y,r:30,fill:cv("--surface"),stroke:cv(col),"stroke-width":role==="L"?3:2}));
    svg.appendChild(el("text",{x:x,y:Y-4,fill:cv("--ink"),"font-size":12,"font-weight":700,"text-anchor":"middle","font-family":cv("--sans")},label));
    svg.appendChild(el("text",{x:x,y:Y+11,fill:cv("--ink-3"),"font-size":10,"text-anchor":"middle","font-family":cv("--mono")},v));
    svg.appendChild(el("text",{x:x,y:Y+48,fill:cv(col),"font-size":10.5,"font-weight":650,"text-anchor":"middle","font-family":cv("--sans")},sub));
  };
  node(zx[0],"N1","L","x=1",S3.part?"--crit":"--ok",S3.part?"僵尸 Leader":"Leader");
  node(zx[1],"N2","F","x=1","--s1","Follower");
  node(mx[0],"N3",S3.part?"L":"F",val,S3.part?"--ok":"--s1",S3.part?"新 Leader":"Follower");
  node(mx[1],"N4","F",val,"--s1","Follower");
  node(mx[2],"N5","F",val,"--s1","Follower");
  svg.appendChild(el("text",{x:175,y:160,fill:cv("--ink-3"),"font-size":11,"text-anchor":"middle","font-family":cv("--sans")},"少数派 2/5"));
  svg.appendChild(el("text",{x:540,y:160,fill:cv("--ink-3"),"font-size":11,"text-anchor":"middle","font-family":cv("--sans")},"多数派 3/5　过半 = 3 ✓"));
  if(S3.read){
    svg.appendChild(el("text",{x:110,y:196,fill:cv("--crit"),"font-size":11.5,"font-weight":700,"text-anchor":"middle","font-family":cv("--sans")},"客户端在这里读 x"));
    svg.appendChild(el("line",{x1:110,y1:182,x2:110,y2:118,stroke:cv("--crit"),"stroke-width":1.5,"stroke-dasharray":"3 3"}));
  }
  let h;
  if(!S3.part) h='<div class="note" style="margin:0"><p style="margin-bottom:0">集群正常，N1 是 Leader，<code>x=1</code>。点「制造分区」开始。</p></div>';
  else if(!S3.written) h='<div class="note warn" style="margin:0"><div class="note-h"><span class="dot" style="background:var(--warn)"></span>分区已持续超过一个选举超时</div>'+
    '<p style="margin-bottom:0">多数派 {N3,N4,N5} 选出了新 Leader N3。<br>'+
    'N1 仍然自认为是 Leader（基础 Raft 不会让它主动退位），它的状态机<strong>冻结在 x=1</strong>。<br>'+
    '现在点第 ② 步，让客户端向<em>新</em> Leader 写入。</p></div>';
  else if(!S3.read) h='<div class="note ok" style="margin:0"><div class="note-h"><span class="dot" style="background:var(--ok)"></span>写入成功</div>'+
    '<p style="margin-bottom:0">客户端向 N3 写 <code>x=99</code>，复制到 {N3,N4,N5} 过半，<strong>提交并回复客户端成功</strong>。<br>'+
    '而 N1、N2 那边完全不知情，它们的状态机还停在 <code>x=1</code>。<br>'+
    '现在点第 ③ 步：客户端（比如被 DNS 或连接池路由到了 N1）从僵尸 Leader 读 x。</p></div>';
  else h='<div class="note crit" style="margin:0"><div class="note-h"><span class="dot" style="background:var(--crit)"></span>三种读，三种结果</div>'+
    '<table style="margin:10px 0 0"><thead><tr><th style="width:22%">读的实现</th><th style="width:22%">返回什么</th><th>为什么</th></tr></thead><tbody>'+
    '<tr><td><strong>① 本地读</strong></td><td><strong style="color:var(--crit)">x=1（陈旧）</strong></td>'+
    '<td>N1 直接读自己的状态机就返回。<strong>不报错、无日志、无痕迹</strong>——客户端刚从 N3 拿到"写入成功"，转头就读到旧值，线性一致性当场破裂。</td></tr>'+
    '<tr><td><strong>② ReadIndex</strong></td><td><strong style="color:var(--ok)">报错</strong></td>'+
    '<td>N1 读之前先发一轮心跳确认自己还是主，但只有 N2 响应（1/5 &lt; 过半 3）⇒ <strong>它发现自己已经不是合法 Leader，拒绝服务</strong>。<em>给你错误，而不是给你错的数据。</em></td></tr>'+
    '<tr><td><strong>③ Lease Read</strong></td><td><strong style="color:var(--ok)">报错</strong></td>'+
    '<td>N1 的租约在收不到过半心跳响应后就没再续上，而现在已经过了一个选举超时（租约比它更短），<strong>租约早已过期</strong> ⇒ 拒绝本地读。</td></tr>'+
    '</tbody></table>'+
    '<p style="margin:12px 0 0"><strong>关于 Lease Read 的那个窗口</strong>：在分区刚发生、租约还没过期的那一小段时间里，N1 确实会直接本地返回 <code>x=1</code>。'+
    '但那段时间内<em>新 Leader 还不可能产生</em>（选举超时比租约长），所以 <code>x=1</code> 当时仍是全集群的最新值——<strong>仍然线性一致</strong>。<br>'+
    '这个论证成立的前提是 <strong>时钟漂移有界</strong>。如果 N1 的时钟突然变慢，它会以为租约还没到期而继续本地读——'+
    '<em>Part 1 那个坑，在这里变成了一致性问题。</em>这就是 ReadIndex（用一次网络往返买安全）和 Lease Read（用一个时钟假设买安全）的根本区别。</p></div>';
  $("#o3").innerHTML=h;
}
$("#b3part").onclick=()=>{S3.part=true;draw3();};
$("#b3write").onclick=()=>{if(S3.part){S3.written=true;draw3();}};
$("#b3read").onclick=()=>{if(S3.written){S3.read=true;draw3();}};
$("#b3reset").onclick=()=>{S3.part=S3.written=S3.read=false;draw3();};
draw3();
})();
</script>
</body>
</html>
EOF
